{"command":"python3 -c "
def parse_srt(path):
    blocks = []
    with open(path) as f:
        content = f.read()
    for part in content.strip().split('\n\n'):
        lines = [l.strip() for l in part.strip().split('\n') if l.strip()]
        # SRT format: idx, timestamp(contains -->), text...
        ts_idx = None
        for i, l in enumerate(lines):
            if '-->' in l:
                ts_idx = i
                break
        if ts_idx is not None and ts_idx + 1 < len(lines):
            text = '\n'.join(lines[ts_idx+1:])
            blocks.append({'text': text})
    return blocks

